nextflow_process {

    name "Test Process FMHFUNPROFILER"
    script "../main.nf"
    process "FMHFUNPROFILER"

    tag "modules"
    tag "modules_nfcore"
    tag "fmhfunprofiler"
    tag "sourmash"
    tag "sourmash/sketch"

    setup {
        run("SOURMASH_SKETCH") {
            script "../../sourmash/sketch/main.nf"
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                input[1] =  false // false means do _not_ merge sigs
                """
            }
        }
    }

    test("sarscov2 - fastq - single_end") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:true ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                ]
                input[1] = SOURMASH_SKETCH.out.signatures.map { meta, sig -> sig }
                input[2] = 11
                input[3] = 1000
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("sarscov2 - fastq - single_end - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [ [ id:'test', single_end:true ], [] ]
                input[1] = []
                input[2] = 11
                input[3] = 1000
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

